using System;
using System.Linq;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using LWS.TruckHockey;
namespace LWS.TruckSports {
public sealed class HockeyExtendedSmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> records=new List<string>();HockeyMatch m;Keyboard keyboard;InputSettings original,probe;string folder;bool done,error,measure;readonly List<float> frames=new List<float>(15000);
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsIceContact")<0)return;var g=new GameObject("Ice Hockey contact/clearance validation");DontDestroyOnLoad(g);g.AddComponent<HockeyExtendedSmoke>();}
 void Start(){folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../IceContactEvidence"));Directory.CreateDirectory(folder);original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Ice software keyboard");InputSystem.QueueStateEvent(keyboard,new KeyboardState());Application.logMessageReceived+=Log;steps.Push(Run());}
 void Log(string s,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){error=true;records.Add("ERROR "+s);}}void Check(bool b,string label){if(!b)throw new Exception(label);records.Add("PASS "+label);Debug.Log("ICE_CONTACT_PASS "+label);}void Note(string label){records.Add(label);Debug.Log("ICE_CONTACT_EVIDENCE "+label);}
 IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}IEnumerator Wait(Func<bool> predicate,float seconds,string label){float end=Time.realtimeSinceStartup+seconds;while(!predicate()){if(Time.realtimeSinceStartup>end)throw new Exception("Timeout "+label);yield return null;}}
 void Update(){if(measure&&m!=null&&m.rules.Live)frames.Add(Time.unscaledDeltaTime*1000);if(done)return;try{while(steps.Count>0){var s=steps.Peek();if(!s.MoveNext()){steps.Pop();continue;}if(s.Current is IEnumerator child){steps.Push(child);continue;}return;}Finish(error?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError(e);Finish(2);}}
 void Finish(int code){done=true;Time.timeScale=1;if(keyboard.added)InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;Destroy(probe);File.WriteAllLines(Path.Combine(folder,"results.txt"),records);Application.Quit(code);}void Capture(string name){ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));}
 void ResetOthers(){for(int i=0;i<6;i++)m.trucks[i].ResetBody(new Vector3(-15+i*5,.36f,0),Quaternion.identity);m.puck.position=new Vector3(0,.12f,-5);m.puck.linearVelocity=Vector3.zero;Physics.SyncTransforms();}
 IEnumerator Run(){yield return Delay(.5f);SportsNavigation.LoadSport(SportsNavigation.Hockey);yield return Delay(.5f);m=FindAnyObjectByType<HockeyMatch>();m.mode=HockeyMode.SharedKeyboard;m.Configure();m.durationMinutes=3;Check(m.StartMatch(),"six software-keyboard sources start");yield return Wait(()=>m.rules.Live,5,"countdown");
  foreach(var test in new[]{new Vector3(.8f,0,0),new Vector3(7,0,-7),new Vector3(11,0,2.7f)}){ResetOthers();m.trucks[0].ResetBody(new Vector3(-2,.36f,test.z),Quaternion.Euler(0,90,0));m.trucks[1].ResetBody(new Vector3(1,.36f,0),Quaternion.Euler(0,90,0));m.trucks[0].body.linearVelocity=Vector3.right*test.x;m.trucks[1].body.linearVelocity=test.z==0?Vector3.zero:Vector3.left*Mathf.Min(7,test.x);yield return Delay(1);foreach(var truck in m.trucks)Check(truck.body.linearVelocity.magnitude<=25.01f,"bounded gentle/equal/glancing speed "+test);Note("Pair variant="+test+" v0="+m.trucks[0].body.linearVelocity+" v1="+m.trucks[1].body.linearVelocity);}
  ResetOthers();for(int i=0;i<6;i++){m.trucks[i].ResetBody(new Vector3((i%3-1)*1.4f,.36f,(i<3?-1:1)*2),Quaternion.Euler(0,i<3?0:180,0));m.trucks[i].body.linearVelocity=new Vector3(0,0,i<3?10:-10);}yield return Delay(.8f);foreach(var t in m.trucks)Check(t.body.linearVelocity.magnitude<=25.01f,"pileup response remains capped "+t.side);int hits=m.impacts.StrongHits;yield return Delay(.12f);Check(m.impacts.StrongHits-hits<8,"sustained contacts do not form an impulse loop");
  ResetOthers();var owner=m.trucks[0];var stick=owner.stick;owner.ResetBody(new Vector3(0,.36f,0),Quaternion.identity);yield return Delay(.6f);var first=stick.bladeBody.position;owner.Control(-1,.8f,false);owner.body.linearVelocity=Vector3.right*5;yield return Delay(.15f);Check(Vector3.Distance(stick.bladeBody.position,first)>.15f,"reverse steering and drift move articulated blade independently");owner.ClearInput();
  foreach(var obstacle in stick.obstacles.Where((c,i)=>c!=null&&(c.name.Contains("Goal")||c.name.Contains("goal")||i%7==0)).Take(24)){if(obstacle==null||obstacle.bounds.size.y<.3f)continue;var closest=obstacle.ClosestPoint(new Vector3(0,.4f,0));var toward=(closest-new Vector3(0,.4f,0));toward.y=0;if(toward.sqrMagnitude<4)continue;var p=closest-toward.normalized*.85f;p.y=.36f;owner.ResetBody(p,Quaternion.LookRotation(toward,Vector3.up));m.puck.position=new Vector3(0,.12f,-4);m.puck.linearVelocity=Vector3.zero;Physics.SyncTransforms();yield return Delay(.55f);if(stick.blade.enabled){var b=stick.blade.bounds;bool overlap=Physics.ComputePenetration(stick.blade,stick.blade.transform.position,stick.blade.transform.rotation,obstacle,obstacle.transform.position,obstacle.transform.rotation,out _,out float distance);Check(!overlap||distance<.01f,"enabled blade clears obstacle "+obstacle.name);}Check(m.puck.linearVelocity.magnitude<.01f,"tuck/side-change does not shoot distant puck "+obstacle.name);}
  Screen.SetResolution(1280,720,false);yield return Delay(.4f);Capture("blade-clearance-720");yield return Delay(.2f);m.ChangeSetup();m.mode=HockeyMode.AIVsAI;m.Configure();m.durationMinutes=1;Check(m.StartMatch(),"six-AI match after contact fixtures");measure=true;Time.timeScale=1;yield return Wait(()=>m.rules.Phase==HockeyPhase.Finished,230,"six-AI regulation/overtime");measure=false;frames.Sort();float total=0;foreach(float value in frames)total+=value;Note("Six-truck real-time frames="+frames.Count+" meanMS="+(total/Mathf.Max(1,frames.Count))+" p95="+frames[(int)((frames.Count-1)*.95f)]+" p99="+frames[(int)((frames.Count-1)*.99f)]+" max="+frames[frames.Count-1]+" GPU="+SystemInfo.graphicsDeviceName);Time.timeScale=1;Note("Six-AI goals="+m.rules.Goals+" emergencyFaceoffs="+m.EmergencyFaceoffs+" hits="+m.impacts.StrongHits);Screen.SetResolution(1920,1080,false);yield return Delay(.4f);Capture("six-ai-result-1080");yield return Delay(.2f);SportsNavigation.FrontEnd();yield return Delay(.5f);Check(FindAnyObjectByType<SportsFrontEnd>()!=null,"Ice contact validation returns to collection");}
 void OnDestroy(){Application.logMessageReceived-=Log;}
#endif
}
}
